export { default as OrderBook } from "./src/OrderBook.vue";
export { default as OrderBookBalance } from "./src/OrderBookBalance.vue";
export { default as OrderBookDepthRow } from "./src/OrderBookDepthRow.vue";
export { default as OrderBookDepthSummary } from "./src/OrderBookDepthSummary.vue";
export { default as OrderBookHeader } from "./src/OrderBookHeader.vue";
export { default as OrderBookSide } from "./src/OrderBookSide.vue";
export { default as OrderBookSpread } from "./src/OrderBookSpread.vue";
export { useOrderBook } from "./src/context";
export type {
  OrderBookProps,
  OrderBookLevel,
  OrderBookActiveLevel,
} from "./src/context";
export type {
  DepthLevel as OrderBookDepthLevel,
  DepthSummary as OrderBookDepthSummaryData,
} from "./src/model";
export type OrderBookSideProps = InstanceType<
  (typeof import("./src/OrderBookSide.vue"))["default"]
>["$props"];
export type OrderBookDepthSummaryProps = InstanceType<
  (typeof import("./src/OrderBookDepthSummary.vue"))["default"]
>["$props"];
export type OrderBookDepthRowProps = InstanceType<
  (typeof import("./src/OrderBookDepthRow.vue"))["default"]
>["$props"];
export type OrderBookHeaderProps = InstanceType<
  (typeof import("./src/OrderBookHeader.vue"))["default"]
>["$props"];
export type OrderBookBalanceProps = InstanceType<
  (typeof import("./src/OrderBookBalance.vue"))["default"]
>["$props"];
export type OrderBookSpreadProps = InstanceType<
  (typeof import("./src/OrderBookSpread.vue"))["default"]
>["$props"];

import { computed, getCurrentInstance, reactive } from "vue";
import { useReducedMotion } from "../../../lib/composables";
import { selection, context, formatCompact } from "../../shared";
import { buildOrderBook, summarizeDepth, type DepthLevel } from "./model";
export type OrderBookLevel = { price: number; size: number };
export type OrderBookActiveLevel = {
  side: "bid" | "ask";
  price: number;
} | null;
export interface OrderBookProps {
  bids: readonly OrderBookLevel[];
  asks: readonly OrderBookLevel[];
  levels?: number;
  lastPrice?: number;
  label?: string;
  baseSymbol?: string;
  quoteSymbol?: string;
  formatPrice?: (value: number) => string;
  formatSize?: (value: number) => string;
  activeLevel?: OrderBookActiveLevel;
  defaultActiveLevel?: OrderBookActiveLevel;
  className?: string;
}
const priceFormat = new Intl.NumberFormat("en-US", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
export function createOrderBookModel(
  props: OrderBookProps,
  emit: (event: any, ...args: any[]) => void,
) {
  const instance = getCurrentInstance();
  const book = computed(() =>
    buildOrderBook(props.bids, props.asks, props.levels ?? 9),
  );
  const selectionState = selection(
    () => props.activeLevel,
    props.defaultActiveLevel ?? null,
    (value) => {
      emit("update:activeLevel", value);
      emit("activeLevelChange", value);
    },
  );
  const active = computed(() => {
    const selected = selectionState.value;
    if (!selected) return null;
    const rows = selected.side === "bid" ? book.value.bids : book.value.asks;
    const index = rows.findIndex((row) => row.price === selected.price);
    return index < 0 ? null : { side: selected.side, index };
  });
  const summary = computed(() => {
    if (!active.value) return null;
    const side = active.value.side;
    const rows = side === "bid" ? book.value.bids : book.value.asks;
    return summarizeDepth(rows.slice(0, active.value.index + 1), side);
  });
  return reactive({
    book,
    active,
    summary,
    selectable: computed(() => Boolean(instance?.vnode.props?.onLevelSelect)),
    bids: computed(() => book.value.bids),
    asks: computed(() => book.value.asks),
    bidTotal: computed(() => book.value.bidTotal),
    askTotal: computed(() => book.value.askTotal),
    maxTotal: computed(() => book.value.maxTotal),
    spread: computed(() => book.value.spread),
    midpoint: computed(() => book.value.midpoint),
    price: computed(() =>
      props.lastPrice != null &&
      Number.isFinite(props.lastPrice) &&
      props.lastPrice > 0
        ? props.lastPrice
        : book.value.midpoint,
    ),
    setActiveLevel(value: OrderBookActiveLevel) {
      selectionState.value = value;
    },
    select(value: DepthLevel, side: "bid" | "ask") {
      emit("levelSelect", value, side);
    },
    label: computed(() => props.label ?? "Order book"),
    baseSymbol: computed(() => props.baseSymbol ?? ""),
    quoteSymbol: computed(() => props.quoteSymbol ?? "USD"),
    formatPrice: computed(
      () => props.formatPrice ?? ((value: number) => priceFormat.format(value)),
    ),
    formatSize: computed(() => props.formatSize ?? formatCompact),
    reduce: useReducedMotion(),
  });
}
export const orderBookContext =
  context<ReturnType<typeof createOrderBookModel>>("OrderBook");
export const useOrderBook = orderBookContext.use;

export type DepthLevel = { price: number; size: number; total: number };
type Level = { price: number; size: number };
export type DepthSummary = {
  side: "bid" | "ask";
  levels: number;
  size: number;
  quote: number;
  averagePrice: number;
};

function sideDepth(
  source: readonly Level[],
  descending: boolean,
  count: number,
): DepthLevel[] {
  const sizes = new Map<number, number>();
  source.forEach(({ price, size }) => {
    if (
      price > 0 &&
      size > 0 &&
      Number.isFinite(price) &&
      Number.isFinite(size)
    )
      sizes.set(price, (sizes.get(price) ?? 0) + size);
  });
  const prices = [...sizes.keys()]
    .sort((a, b) => (descending ? b - a : a - b))
    .slice(0, count);
  const result: DepthLevel[] = [];
  let cumulative = 0;
  for (const price of prices) {
    const size = sizes.get(price)!;
    cumulative += size;
    result.push({ price, size, total: cumulative });
  }
  return result;
}

export function summarizeDepth(
  levels: readonly DepthLevel[],
  side: "bid" | "ask",
): DepthSummary {
  let size = 0;
  let quote = 0;
  for (const level of levels) {
    size += level.size;
    quote += level.price * level.size;
  }
  return {
    side,
    levels: levels.length,
    size,
    quote,
    averagePrice: size ? quote / size : 0,
  };
}

export function buildOrderBook(
  bids: readonly Level[],
  asks: readonly Level[],
  levels: number,
) {
  const count = Number.isFinite(levels) ? Math.max(0, Math.floor(levels)) : 9;
  const result = {
    bids: sideDepth(bids, true, count),
    asks: sideDepth(asks, false, count),
  };
  const bidTotal = result.bids.at(-1)?.total ?? 0;
  const askTotal = result.asks.at(-1)?.total ?? 0;
  const bid = result.bids[0];
  const ask = result.asks[0];
  return {
    ...result,
    bidTotal,
    askTotal,
    maxTotal: Math.max(bidTotal, askTotal),
    midpoint: bid && ask ? (bid.price + ask.price) / 2 : null,
    spread: bid && ask ? ask.price - bid.price : null,
  };
}

import {
  computed,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  watch,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from "vue";

const numeric = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });
const compact = new Intl.NumberFormat("en-US", {
  notation: "compact",
  maximumFractionDigits: 1,
});
export const formatNumber = (value: number) => numeric.format(value);
export const formatCompact = (value: number) => compact.format(value);

export function context<T>(name: string) {
  const key: InjectionKey<T> = Symbol(name);
  function use(): T {
    const provided = inject(key);
    if (provided === undefined || provided === null)
      throw new Error(`${name} parts must be rendered inside ${name}.`);
    return provided;
  }
  return { key, use };
}

export function selection<T>(
  get: () => T | undefined,
  initial: T,
  change: (value: T) => void,
) {
  const fallback = ref(initial) as Ref<T>;
  return computed<T>({
    get() {
      const supplied = get();
      return supplied === undefined ? fallback.value : supplied;
    },
    set(value) {
      if (get() === undefined) fallback.value = value;
      change(value);
    },
  });
}

export function activeSelection(
  get: () => string | null | undefined,
  initial: string | null,
  ids: ComputedRef<string[]>,
  change: (id: string | null) => void,
) {
  const requested = selection(get, initial, change);
  const available = computed(() => new Set(ids.value));
  watch(available, (current) => {
    const id = requested.value;
    if (get() === undefined && id !== null && !current.has(id))
      requested.value = null;
  });
  return computed<string | null>({
    get() {
      const id = requested.value;
      return id !== null && available.value.has(id) ? id : null;
    },
    set: (id) => {
      requested.value = id;
    },
  });
}

export function usePlotSize(
  element: Ref<HTMLElement | null>,
  initial: { width: number; height: number },
) {
  const size = ref({ ...initial });
  let observer: ResizeObserver | undefined;
  let stop: (() => void) | undefined;
  onMounted(() => {
    if (typeof ResizeObserver === "undefined") return;
    observer = new ResizeObserver((entries) => {
      const entry = entries.find((item) => item.target === element.value);
      const box = entry?.contentRect;
      if (
        box &&
        box.width > 0 &&
        box.height > 0 &&
        (box.width !== size.value.width || box.height !== size.value.height)
      )
        size.value = { width: box.width, height: box.height };
    });
    stop = watch(
      element,
      (current, previous) => {
        if (previous) observer?.unobserve(previous);
        if (current) observer?.observe(current);
      },
      { immediate: true },
    );
  });
  onBeforeUnmount(() => {
    stop?.();
    observer?.disconnect();
  });
  return size;
}

export function moveFocus(
  event: KeyboardEvent,
  index: number,
  count: number,
  columns = 1,
) {
  if (count <= 0) return;
  const stride = Math.max(1, columns);
  const rowStart = Math.floor(index / stride) * stride;
  const destinations: Record<string, number> = {
    ArrowRight: index + 1,
    ArrowLeft: index - 1,
    ArrowDown: index + stride,
    ArrowUp: index - stride,
    Home: event.ctrlKey ? 0 : rowStart,
    End: event.ctrlKey ? count - 1 : rowStart + stride - 1,
  };
  if (!(event.key in destinations)) return;
  event.preventDefault();
  const current = event.currentTarget;
  if (!(current instanceof HTMLElement)) return;
  const entries = current
    .closest("[data-chart-keyboard]")
    ?.querySelectorAll<HTMLElement>("[data-chart-item]");
  const destination = Math.max(0, Math.min(count - 1, destinations[event.key]));
  entries?.[destination]?.focus();
}

export function unwrapModel<T extends object>(model: ComputedRef<T>): T {
  const descriptors = Object.fromEntries(
    Object.keys(model.value).map((key) => [
      key,
      {
        enumerable: true,
        get: () => model.value[key as keyof T],
      },
    ]),
  );
  return Object.defineProperties({} as T, descriptors);
}

import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";
import { layerManager, type Layer } from "./layers";

export function useControllable<T>(props: Record<string, any>, key: string, emit: (...args: any[]) => void, fallback: T) {
  const local = ref<T>(fallback) as Ref<T>;
  const read = () => props[key] as T | undefined;
  return computed<T>({
    get() { const supplied = read(); return supplied === undefined ? local.value : supplied; },
    set(value) { if (read() === undefined) local.value = value; emit(`update:${key}`, value); },
  });
}

export function useMediaQuery(query: string) {
  const matches = ref(false);
  let disconnect: (() => void) | undefined;
  onMounted(() => {
    if (typeof window.matchMedia !== "function") return;
    const media = window.matchMedia(query);
    const update = () => { matches.value = media.matches; };
    update();
    media.addEventListener?.("change", update);
    disconnect = () => media.removeEventListener?.("change", update);
  });
  onBeforeUnmount(() => disconnect?.());
  return matches;
}
export function useReducedMotion() { return useMediaQuery("(prefers-reduced-motion: reduce)"); }

const lockedProperties = ["overflow", "position", "top", "left", "right", "width"] as const;
let scrollOwners = 0;
let unlockPage: (() => void) | undefined;
function acquirePage() {
  if (scrollOwners++ === 0) {
    const body = document.body.style;
    const saved = lockedProperties.map(name => ({ name, value: body.getPropertyValue(name), priority: body.getPropertyPriority(name) }));
    const x = window.scrollX, y = window.scrollY;
    body.setProperty("overflow", "hidden");
    body.setProperty("position", "fixed");
    body.setProperty("left", `${-x}px`);
    body.setProperty("top", `${-y}px`);
    body.setProperty("right", "0px");
    body.setProperty("width", "100%");
    unlockPage = () => {
      for (const entry of saved) {
        if (entry.value) body.setProperty(entry.name, entry.value, entry.priority);
        else body.removeProperty(entry.name);
      }
      const root = document.documentElement.style;
      const behavior = root.getPropertyValue("scroll-behavior");
      const priority = root.getPropertyPriority("scroll-behavior");
      root.setProperty("scroll-behavior", "auto");
      window.scrollTo(x, y);
      if (behavior) root.setProperty("scroll-behavior", behavior, priority);
      else root.removeProperty("scroll-behavior");
    };
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--scrollOwners === 0) { unlockPage?.(); unlockPage = undefined; }
  };
}
export function useScrollLock(locked: Ref<boolean>) {
  let mounted = false;
  let release: (() => void) | undefined;
  const update = (value: boolean) => {
    if (!mounted) return;
    if (value && !release) release = acquirePage();
    if (!value && release) { release(); release = undefined; }
  };
  onMounted(() => { mounted = true; update(locked.value); });
  watch(locked, update);
  onBeforeUnmount(() => { release?.(); release = undefined; mounted = false; });
}

export function resolveElement<T extends Element = HTMLElement>(value: unknown): T | null {
  if (!value) return null;
  const unwrapped = (value as { $el?: unknown }).$el ?? value;
  return typeof (unwrapped as Element).nodeType === "number" && (unwrapped as Element).nodeType === 1 ? unwrapped as T : null;
}
const focusable = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function createLayer(modal: boolean, panel?: { readonly value: unknown }): Layer {
  return { key: Symbol("orvui-layer"), modal, owner: getCurrentInstance(), surface: () => resolveElement(panel?.value), returnTo: null };
}
export function useOverlay(open: Ref<boolean>, panel: Ref<HTMLElement | null>, close: () => void, initialFocus?: () => HTMLElement | undefined) {
  const layer = createLayer(true, panel);
  let mounted = false;
  let revision = 0;
  const sync = async (value: boolean) => {
    const current = ++revision;
    if (!mounted) return;
    if (!value) { layerManager.detach(layer, true); return; }
    if (!layerManager.attach(layer)) return;
    await nextTick();
    if (!mounted || current !== revision || !open.value || !layerManager.top(layer)) return;
    (initialFocus?.() ?? layer.surface()?.querySelector<HTMLElement>(focusable) ?? layer.surface())?.focus({ preventScroll: true });
  };
  const onKey = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !open.value) return;
    if (event.key === "Escape" && layerManager.top(layer)) {
      event.preventDefault(); event.stopPropagation(); close(); return;
    }
    if (event.key !== "Tab" || !layerManager.modal(layer)) return;
    const candidates = new Set<HTMLElement>();
    for (const surface of layerManager.scopes(layer)) {
      for (const node of surface.querySelectorAll<HTMLElement>(focusable)) {
        if (node.getClientRects().length > 0 && !node.closest("[inert]")) candidates.add(node);
      }
    }
    event.preventDefault();
    const nodes = [...candidates];
    if (!nodes.length) { layer.surface()?.focus(); return; }
    const position = nodes.indexOf(document.activeElement as HTMLElement);
    const next = position < 0 ? (event.shiftKey ? nodes.length - 1 : 0) : (position + (event.shiftKey ? -1 : 1) + nodes.length) % nodes.length;
    nodes[next].focus();
  };
  useScrollLock(open);
  onMounted(() => { mounted = true; document.addEventListener("keydown", onKey); void sync(open.value); });
  watch(open, value => void sync(value));
  onBeforeUnmount(() => { mounted = false; revision++; document.removeEventListener("keydown", onKey); layerManager.detach(layer, true); });
  return {
    isTop: () => open.value && layerManager.top(layer),
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
    containsOwnedPortal: (target: HTMLElement) => layerManager.containsPortal(layer.owner, target),
  };
}
export function useFloatingLayer(open: Ref<boolean>, panel?: { readonly value: unknown }) {
  const layer = createLayer(false, panel);
  let mounted = false;
  let unregister: (() => void) | undefined;
  const sync = (value: boolean) => {
    if (!mounted) return;
    if (value) layerManager.attach(layer); else layerManager.detach(layer, false);
  };
  onMounted(() => { mounted = true; unregister = layerManager.portal(layer.owner, layer.surface); sync(open.value); });
  watch(open, sync, { flush: "sync" });
  onBeforeUnmount(() => { mounted = false; unregister?.(); layerManager.detach(layer, false); });
  const isTop = () => open.value && layerManager.top(layer);
  return {
    isTop,
    claimEscape(event: KeyboardEvent) {
      if (event.key !== "Escape" || event.defaultPrevented || !isTop()) return false;
      event.preventDefault(); event.stopImmediatePropagation(); return true;
    },
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
  };
}
export function useEventListener(target: () => EventTarget | null | undefined, event: string, handler: EventListener, options?: AddEventListenerOptions) {
  let remove: (() => void) | undefined;
  onMounted(() => { const element = target(); element?.addEventListener(event, handler, options); remove = () => element?.removeEventListener(event, handler, options); });
  onBeforeUnmount(() => remove?.());
}

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;
export const EASE_OUT_CSS = "cubic-bezier(0.16,1,0.3,1)";
export const SPRING_PRESS = {
  type: "spring",
  stiffness: 500,
  damping: 30,
  mass: 0.6,
} as const;
export const SPRING_SWAP = {
  type: "spring",
  stiffness: 460,
  damping: 30,
  mass: 0.55,
} as const;
export const SPRING_PANEL = {
  type: "spring",
  stiffness: 420,
  damping: 40,
  mass: 0.5,
} as const;
export const SPRING_LAYOUT = {
  type: "spring",
  stiffness: 360,
  damping: 32,
  mass: 0.6,
} as const;
export const SPRING_MOUSE = { stiffness: 200, damping: 15, mass: 0.3 } as const;
export const SPRING_GLIDE = { stiffness: 700, damping: 50, mass: 0.5 } as const;
export const SPRING_TIMELINE = {
  type: "spring",
  stiffness: 120,
  damping: 24,
  mass: 1,
} as const;

// Only ancestry is required; Vue 3.6 parents can also be generic component instances.
type ComponentOwner = { readonly parent: ComponentOwner | null };

type Surface = () => HTMLElement | null;
export interface Layer {
  key: symbol;
  modal: boolean;
  owner: ComponentOwner | null;
  surface: Surface;
  returnTo: HTMLElement | null;
}
const active: Layer[] = [];
const portals = new Set<{ owner: ComponentOwner | null; surface: Surface }>();

function belongsTo(child: ComponentOwner | null, parent: ComponentOwner | null) {
  if (!parent) return false;
  for (let node = child; node; node = node.parent) if (node === parent) return true;
  return false;
}
function later(layer: Layer) {
  const index = active.indexOf(layer);
  return index < 0 ? [] : active.slice(index + 1);
}
export const layerManager = {
  attach(layer: Layer) {
    if (active.includes(layer)) return false;
    layer.returnTo = document.activeElement as HTMLElement | null;
    const before = active.findIndex(entry => entry.owner !== layer.owner && belongsTo(entry.owner, layer.owner));
    active.splice(before < 0 ? active.length : before, 0, layer);
    return true;
  },
  detach(layer: Layer, restore: boolean) {
    const index = active.indexOf(layer);
    if (index < 0) return;
    const wasLast = index === active.length - 1;
    const surface = layer.surface();
    for (const successor of later(layer)) {
      if (successor.returnTo && surface?.contains(successor.returnTo)) successor.returnTo = layer.returnTo;
    }
    active.splice(index, 1);
    if (restore && wasLast && layer.returnTo?.isConnected) layer.returnTo.focus({ preventScroll: true });
  },
  top(layer: Layer) { return active.at(-1) === layer; },
  modal(layer: Layer) { return active.slice().reverse().find(entry => entry.modal) === layer; },
  higher(layer: Layer, target: EventTarget | null) {
    return !!target && typeof (target as Node).nodeType === "number" && later(layer).some(entry => entry.surface()?.contains(target as Node));
  },
  scopes(layer: Layer) {
    const result = [layer.surface()];
    for (const entry of later(layer)) if (!entry.modal && belongsTo(entry.owner, layer.owner)) result.push(entry.surface());
    return result.filter((surface): surface is HTMLElement => surface !== null);
  },
  portal(owner: ComponentOwner | null, surface: Surface) {
    const portal = { owner, surface };
    portals.add(portal);
    return () => portals.delete(portal);
  },
  containsPortal(owner: ComponentOwner | null, target: HTMLElement) {
    for (const portal of portals) {
      const node = portal.surface();
      if (node && belongsTo(portal.owner, owner) && target.contains(node)) return true;
    }
    return false;
  },
};

@import "tailwindcss";
@import "./tokens.css";
@source "./**/*.{vue,ts}";
@source not "./**/tests/**";
@custom-variant dark (&:where(.dark, .dark *));

:root { --announcement-h: 2.5rem; }

@theme {
  --background-image-brand-bg: var(--gradient-bg);
  --background-image-brand-accent: var(--gradient-accent);
  --animate-marquee: marquee 30s linear infinite;
  --animate-marquee-vertical: marquee-vertical 30s linear infinite;
  --animate-rainbow-border: rainbow-border 3s linear infinite;
  --animate-shimmer: shimmer 2.5s linear infinite;
  --animate-action-send: action-send 520ms var(--ease-out) both;
  --animate-action-copy: action-copy 520ms var(--ease-out) both;
  --animate-action-download: action-download 540ms var(--ease-out) both;
  --animate-action-archive: action-archive 520ms var(--ease-out) both;
  --animate-action-bell: action-bell 680ms var(--ease-out) both;
  --animate-action-settings: action-settings 720ms var(--ease-out) both;
}

/* Named motion tracks are part of the public styling contract. */
@keyframes marquee { to { transform: translateX(calc(-100% - var(--gap, 1rem))); } }
@keyframes marquee-vertical { to { transform: translateY(calc(-100% - var(--gap, 1rem))); } }
@keyframes rainbow-border {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}
@keyframes shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@keyframes action-send {
  0%, 100% { transform: translate(0, 0); }
  45% { transform: translate(2px, -2px); }
}
@keyframes action-copy {
  0%, 100% { transform: translate(0, 0); }
  40% { transform: translate(1.5px, -1.5px); }
  70% { transform: translate(-1px, 1px); }
}
@keyframes action-download {
  0%, 100% { transform: translateY(0); }
  42% { transform: translateY(2.5px); }
}
@keyframes action-archive {
  0%, 100% { transform: scale(1); }
  45% { transform: scale(0.9); }
}
@keyframes action-bell {
  0%, 100% { transform: rotate(0deg); }
  18% { transform: rotate(14deg); }
  36% { transform: rotate(-12deg); }
  54% { transform: rotate(8deg); }
  72% { transform: rotate(-5deg); }
}
@keyframes action-settings {
  from { transform: rotate(0deg); }
  to { transform: rotate(90deg); }
}

@layer base {
  html, body { overflow-x: clip; }
  html { color-scheme: light dark; }
  body {
    font-family: var(--font-sans);
    color: var(--foreground);
    background: var(--background);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  a, button:not(:disabled), [role="button"]:not(:disabled) { cursor: pointer; }
  ::selection {
    color: var(--foreground);
    background: color-mix(in oklch, var(--accent) 30%, transparent);
  }
  .shiki, .shiki span { color: var(--shiki-light); }
  .dark .shiki, .dark .shiki span { color: var(--shiki-dark); }
}

@layer utilities {
  .text-balance { text-wrap: balance; }
  .text-pretty { text-wrap: pretty; }
  .scrollbar-hide { scrollbar-width: none; }
  .scrollbar-hide::-webkit-scrollbar { display: none; }
  .mask-b-fade { mask-image: linear-gradient(to bottom, black 60%, transparent); }
  .mask-radial-fade { mask-image: radial-gradient(ellipse at center, black 40%, transparent 75%); }
  .grid-noise {
    background-size: 32px 32px;
    background-image: linear-gradient(to right, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px);
  }
  .glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(20px) saturate(160%);
    box-shadow: inset 0 1px 0 0 rgb(255 255 255 / 0.06), 0 24px 60px -24px rgb(0 0 0 / 0.45);
  }
  .glass-strong { background: var(--glass-strong-bg); backdrop-filter: blur(16px); }
  .glass-thin { background: var(--glass-thin-bg); backdrop-filter: blur(12px); border: 1px solid var(--glass-border); }
  .press { transition: transform 120ms var(--ease-out); }
  .press:active { transform: scale(0.97); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

